SELECT record_id, contest_id, user_id, problem_id, status, score,
       applied_attempt_seq, applied_attempt_id
FROM contest_records
WHERE contest_id = #{contestId}
  AND user_id = #{userId}
  AND problem_id = #{problemId}
FOR UPDATE

SELECT COALESCE(SUM(score), 0)
FROM contest_records
WHERE contest_id = #{contestId}
  AND user_id = #{userId}
